}

pub fn normalOf(a: [3]f32, b: [3]f32, c: [3]f32) [3]f32 {
    const ux = b[0] - a[0];
    const uy = b[1] - a[1];
    const uz = b[2] - a[2];
    const vx = c[0] - a[0];
    const vy = c[1] - a[1];
    const vz = c[2] - a[2];
    var n = [3]f32{ uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx };
    const l = @sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);
    if (l > 1e-8) {
        n[0] /= l;
        n[1] /= l;
        n[2] /= l;
    } else {
        n = .{ 0, 1, 0 };
    }
    return n;
}

pub fn copyPaintPositionsToEditVerts(first_face: u32, last_face: u32) bool {
    const verts = z3d.g_edit_verts orelse return false;
    const pos = model_paint.positions() orelse return false;
    if (z3d.g_edit_count == 0 or first_face > last_face) return false;
    const face_count = @min(z3d.g_edit_count / 3, @as(u32, @intCast(pos.len / 9)));
    if (first_face >= face_count) return false;
    const hi = @min(last_face, face_count - 1);
    var f = first_face;
    while (f <= hi) : (f += 1) {
        const pb = @as(usize, f) * 9;
        const a = [3]f32{ pos[pb + 0], pos[pb + 1], pos[pb + 2] };
        const b = [3]f32{ pos[pb + 3], pos[pb + 4], pos[pb + 5] };
        const c = [3]f32{ pos[pb + 6], pos[pb + 7], pos[pb + 8] };
        const n = z3d.normalOf(a, b, c);
        var k: usize = 0;
        while (k < 3) : (k += 1) {
            const vi = @as(usize, f) * 3 + k;
            const dst = vi * 8;
            const src = pb + k * 3;
            if (dst + 7 >= verts.len) continue;
            verts[dst + 0] = pos[src + 0];
            verts[dst + 1] = pos[src + 1];
            verts[dst + 2] = pos[src + 2];
            verts[dst + 3] = n[0];
            verts[dst + 4] = n[1];
            verts[dst + 5] = n[2];
        }
    }
    return true;
}

pub fn patchActiveEditMesh(first_face: u32, last_face: u32) bool {
    const verts = z3d.g_edit_verts orelse return false;
    if (z3d.g_edit_key_hash == 0 or z3d.g_edit_count == 0 or first_face > last_face) return false;
    const first_vert = first_face * 3;
    const face_count = z3d.g_edit_count / 3;
    if (first_face >= face_count) return false;
    const hi = @min(last_face, face_count - 1);
    const vert_count = (hi - first_face + 1) * 3;
    const start_f32 = @as(usize, first_vert) * 8;
    const len_f32 = @as(usize, vert_count) * 8;
    if (start_f32 + len_f32 > verts.len) return false;

    var patched = false;
    for (&z3d.g_host_stash) |*s| {
        if (!s.present or s.hash != z3d.g_edit_key_hash or s.generation != z3d.g_edit_geometry_generation) continue;
        if (s.verts) |stash_verts| {
            if (start_f32 + len_f32 <= stash_verts.len) {
                @memcpy(stash_verts[start_f32 .. start_f32 + len_f32], verts[start_f32 .. start_f32 + len_f32]);
                patched = true;
            }
        }
    }
    const queue = core.getQueue();
    const buf = z3d.g_retained_vbuf;
    if (queue != null and buf != null) {
        for (z3d.g_geo_cache[0..z3d.g_geo_cache_len]) |*e| {
            if (!e.present or e.hash != z3d.g_edit_key_hash or e.generation != z3d.g_edit_geometry_generation) continue;
            if (first_vert + vert_count > e.count) continue;
            z3d.stageVertexRows(
                queue.?,
                buf.?,
                e.offset_bytes + @as(u64, first_vert) * @sizeOf(z3d.Vertex),
                verts[start_f32 .. start_f32 + len_f32],
                vert_count,
            );
            patched = true;
        }
    }
    return patched;
}

/// A CPU mutation is already authoritative by the time the incremental GPU patch
/// runs. If no retained/stashed slot was patchable, retire any current GPU stamp
/// and queue the complete current mesh for the next draw. Returning "not changed"
/// after mutating CPU state makes drag accumulators replay the same cumulative
/// delta on every motion event.
pub fn queueActiveEditMeshUpload() bool {
    const key = z3d.g_edit_key orelse return false;
    const verts = z3d.g_edit_verts orelse return false;
    if (z3d.g_edit_key_hash == 0 or z3d.g_edit_count == 0) return false;
    // Secure the replacement before invalidating the visible retained entry. An
    // allocation failure must leave the last successfully drawn geometry visible.
    const copy = std.heap.c_allocator.alloc(f32, verts.len) catch return false;
    @memcpy(copy, verts);
    for (z3d.g_geo_cache[0..z3d.g_geo_cache_len]) |*entry| {
        if (!entry.present or entry.hash != z3d.g_edit_key_hash or
            entry.generation != z3d.g_edit_geometry_generation) continue;
        // Active edit generations start at one; zero makes the next intern reuse
        // this same retained region while refusing it as current in the meantime.
        entry.generation = 0;
    }
    z3d.installHostMeshCopy(z3d.hashKey(key), z3d.g_edit_geometry_generation, copy, z3d.g_edit_count);
    return true;
}

pub fn applyMeshMutation(m: mesh_edit.Mutation) bool {
    if (!z3d.residentMutationAllowed(.geometry_journal)) return false;
    if (!m.changed) return false;
    if (!z3d.copyPaintPositionsToEditVerts(m.first_face, m.last_face)) return false;
    var mirror_triangulation_changed = false;
    if (z3d.g_indexed_edit_mesh) |*mesh| {
        const verts = z3d.g_edit_verts orelse return false;
        if (!mesh.residentUvsMatch(verts, z3d.g_edit_count / 3) or
            !mesh.updatePositionsFromInterleaved(verts, z3d.g_edit_count / 3))
        {
            z3d.clearIndexedEditMesh();
        } else if (mesh_edit.mirrorMask() != 0 and model_source.count() == z3d.g_edit_count) {
            mirror_triangulation_changed = (mesh.synchronizeMirrorDiagonals(mesh_edit.mirrorMask(), mesh_edit.MIRROR_PLANE_CENTER) catch sync_failed: {
                log.print("[mesh] live mirror could not synchronize indexed quad diagonals\n", .{});
                z3d.clearIndexedEditMesh();
                break :sync_failed 0;
            }) > 0;
        }
    }
    if (mirror_triangulation_changed and !z3d.installMirrorSynchronizedTriangulation()) {
        log.print("[mesh] live mirror diagonal install rejected: same-face metadata invariant failed\n", .{});
        z3d.clearIndexedEditMesh();
    }
    if (model_paint.positions()) |pos| {
        _ = model_source.updateGeometryFromDisplayed(pos, m.first_face, m.last_face);
    }
    if (!z3d.patchActiveEditMesh(m.first_face, m.last_face) and !z3d.queueActiveEditMeshUpload()) {
        // Geometry and journal truth have already changed. Keep the operation's
        // success semantics honest so a held gizmo cannot compound its delta;
        // the next full resident refresh remains able to recover presentation.
        log.print("[mesh] live mutation committed but its render upload could not be queued\n", .{});
    }
    return true;
}

/// Adopt a freshly-parsed mesh (interleaved verts, 8 f32/vert) as the paint target.
/// Rewrites its UVs to the per-face atlas in place, so the SAME verts then uploaded by
/// stashHostMesh carry the paint mapping. Keyed by the intern key so the draw can find
/// it. Called by the load door before stashing.
pub fn setPaintTarget(key: []const u8, verts: []f32, count: u32) void {
    if (!z3d.residentMutationAllowed(.durable_channels)) return;
    // Manual retopology bands belong to one live document topology. A genuine
    // target load must not let an equal face count make another model inherit
    // stale teaching colours; same-document replaces carry them explicitly.
    _ = z3d.clearRetopoBandPreview();
    if (z3d.g_uv_zone) |rows| std.heap.c_allocator.free(rows);
    z3d.g_uv_zone = null;
    z3d.publishUvZoneMask();
    z3d.clearActiveEditMesh();
    paint_program.reset(); // a fresh model starts with an empty stroke program
    // Reset BEFORE the target swaps: reset restores any selection tint, and the saved
    // base patches belong to the OUTGOING atlas — restoring them into the new one
    // would write stale bytes (or silently no-op) wherever the layouts differ.
    mesh_edit.reset(); // topology changed (load, quality re-mesh, or edit replace) → rebuild lazily
    z3d.invalidateMeshAudit(); // the incoming mesh restarts at generation 1; never inherit the last model's facts
    model_paint.setTarget(z3d.hashKey(key), verts, count);
    const need = @as(usize, count) * 8;
    if (verts.len >= need) {
        z3d.g_edit_verts = std.heap.c_allocator.dupe(f32, verts[0..need]) catch null;
        if (z3d.g_edit_verts != null) {
            z3d.g_edit_key = std.heap.c_allocator.dupe(u8, key) catch null;
            z3d.g_edit_key_hash = z3d.hashKey(key);
            z3d.g_edit_count = count;
            z3d.g_edit_generation = 1;
            z3d.g_edit_geometry_generation = 1;
        }
    }
}

/// Replace the displayed topology while retaining the active document handle. This
/// is the stable-handle twin of `setPaintTarget`: paint/selection topology resets,
/// but the caller-visible identity remains unchanged and only the host generation
/// advances.
pub fn setPaintTargetForGeneration(verts: []f32, count: u32) bool {
    if (z3d.g_edit_key == null or z3d.g_edit_key_hash == 0) return false;
    paint_program.reset();
    mesh_edit.reset();
    model_paint.setTarget(z3d.g_edit_key_hash, verts, count);
    const need = @as(usize, count) * 8;
    if (verts.len < need) return false;
    const copy = std.heap.c_allocator.dupe(f32, verts[0..need]) catch return false;
    z3d.clearActiveEditGeometry();
    z3d.g_edit_verts = copy;
    z3d.g_edit_count = count;
    z3d.bumpEditGeometryGeneration();
    return true;
}

/// Install a reversible quality preview and nominate that exact resident topology for
/// the next durable model snapshot. Geometry stays host-resident; only key/count cross
/// the JS door. A structural edit later retains the displayed mesh as the new source and
/// clears this nomination through replaceActiveEditMesh.
pub fn setQualityPaintTarget(key: []const u8, verts: []f32, count: u32) void {
    if (!z3d.residentMutationAllowed(.durable_channels)) return;
    _ = key;
    if (!z3d.setPaintTargetForGeneration(verts, count)) z3d.setPaintTarget("model-quality", verts, count);
    z3d.g_save_displayed_projection = z3d.g_edit_verts != null and z3d.g_edit_count == count;
}

pub fn meshEditActiveKey() ?[]const u8 {
    return z3d.g_edit_key;
}
pub fn meshEditActiveCount() u32 {
    return z3d.g_edit_count;
}
pub fn meshEditGeneration() u32 {
    return z3d.g_edit_generation;
}

/// Narrow, compile-time-only seam for the headless Scene3D interaction tests.
/// The production viewport normally publishes these camera fields during draw;
/// tests need the same projection without constructing a GPU surface.  Reads go
/// through the real welded topology and retained host stash used by mutations.
pub const test_support = if (builtin.is_test) struct {
    pub fn setPaintCamera(eye: [3]f32, target: [3]f32, fov: f32, width: f32, height: f32) void {
        z3d.g_paint_eye = eye;
        z3d.g_paint_target = target;
        z3d.g_paint_fov = fov;
        z3d.g_paint_vp_w = width;
        z3d.g_paint_vp_h = height;
        z3d.g_paint_vp_x = 0;
        z3d.g_paint_vp_y = 0;
    }

    pub fn vertexPosition(vertex: u32) ?[3]f32 {
        if (!mesh_edit.ensureTopologyPub() or vertex >= mesh_edit.vertCount()) return null;
        return mesh_edit.vertPosPub(vertex);
    }

    pub fn hostPresentationIsCurrent() bool {
        if (z3d.g_edit_key_hash == 0 or z3d.g_edit_geometry_generation == 0) return false;
        for (z3d.g_host_stash) |slot| {
            if (slot.present and slot.hash == z3d.g_edit_key_hash and
                slot.generation == z3d.g_edit_geometry_generation and slot.verts != null)
            {
                return true;
            }
        }
        return false;
    }

    pub fn ensureExplicitIndexedCache() bool {
        if (!z3d.ensureIndexedEditMesh()) return false;
        return if (z3d.g_indexed_edit_mesh) |*mesh| mesh.has_explicit_logical_topology else false;
    }

    pub fn exactIndexedSavePromotionRefusal() []const u8 {
        return z3d.g_exact_indexed_save_promotion_refusal;
    }
} else struct {};

/// Park the authoritative active edit copy for first draw. Paint-layout rebuilds
/// and imported UV adoption mutate this copy after setPaintTarget, so stashing the
/// parser's earlier buffer would publish stale UVs.
pub fn stashActiveEditMesh() bool {
    const key = z3d.g_edit_key orelse return false;
    const verts = z3d.g_edit_verts orelse return false;
    return z3d.stashHostMesh(key, verts, z3d.g_edit_count);
}

/// Pre-decode guard shared by host image importers and the painter's commit path.
pub fn paintAtlasImportDimensionsFit(width: u32, height: u32) bool {
    return model_paint.canImportAtlasDimensions(width, height);
}

/// Start a genuinely new model document. Unlike an in-document topology replace or
/// quality remesh, this drops the previous document's focused outliner range so it
/// cannot filter the incoming mesh (req_2953).
pub fn meshEditBeginModel() void {
    if (!z3d.residentMutationAllowed(.durable_channels)) return;
    z3d.g_paint_layout_stale = false;
    z3d.g_save_displayed_projection = false;
    z3d.clearHiddenGroups();
    mesh_edit.resetForModelLoad();
}
